-- Bot Cobra Fase 5: PaymentPromise (promessa de pagamento via WhatsApp).
CREATE TABLE `payment_promises` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `debt_id` BIGINT UNSIGNED NOT NULL, `promised_date` DATE NOT NULL, `promised_amount_cents` BIGINT UNSIGNED NULL, `status` ENUM('ACTIVE', 'FULFILLED', 'OVERDUE', 'REPLACED', 'CANCELED') NOT NULL DEFAULT 'ACTIVE', `source` ENUM('WHATSAPP', 'MANUAL') NOT NULL, `due_reminder_sent_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `payment_promises_public_id_key` (`public_id`), INDEX `payment_promises_tenant_id_debt_id_status_idx` (`tenant_id`, `debt_id`, `status`), INDEX `payment_promises_status_promised_date_idx` (`status`, `promised_date`), CONSTRAINT `payment_promises_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `payment_promises_debt_id_fkey` FOREIGN KEY (`debt_id`) REFERENCES `debts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
